def target(f,text,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f)
 return {'id':f"ar-r{r['rank']}",'form':f,'lemma':f,'part_of_speech':r.get('part_of_speech_source'),'intended_sense':PREFERRED[f],'register':'contemporary standard','variety':'MSA','context_strategy':['scenario_resolution','fairness_comparison','cause_consequence'],'first_introduced':True,'exposures_in_text':max(1,text.count(f)),'source_lexicon':r.get('source_file'),'source_rank':r['rank'],'beyond_base':False}
def qa(items):
 q=[];a=[]
 for i,(t,p,x,ids) in enumerate(items,1):
  z={'id':f'q{i}','type':t,'prompt':p,'answer_id':f'a{i}'}
